using System;
using System.Collections;
using System.IO;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
namespace NexoAvance {
public class CampaignCheck:MonoBehaviour {
    const string Output=@"C:\Users\jose\Documents\Codex\2026-09-22\ho\outputs\Campana";bool failed;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-campaignCheck")<0)return;var g=new GameObject("Pruebas campaña");DontDestroyOnLoad(g);g.AddComponent<CampaignCheck>();}
    void Check(bool ok,string text){failed|=!ok;File.AppendAllText(Path.Combine(Output,"validacion.txt"),(ok?"OK ":"ERROR ")+text+"\n");}
    void Place(ResistancePlayer p,float x,float y=-.15f){var b=p.GetComponent<Rigidbody2D>();b.position=new Vector2(x,y);p.transform.position=b.position;b.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
    void Setup(CampaignMission m){m.session.player.TestMode=true;m.session.player.SetPaused(false);m.boss.AutoFire=false;foreach(var e in FindObjectsByType<StreetEnemy>(FindObjectsInactive.Include,FindObjectsSortMode.None))e.AutoFire=false;}
    IEnumerator Start(){Directory.CreateDirectory(Output);File.WriteAllText(Path.Combine(Output,"validacion.txt"),"");Application.runInBackground=true;
        yield return SceneManager.LoadSceneAsync("CallesBajoControl");yield return null;var street=FindAnyObjectByType<StreetMission>();street.session.player.TestMode=true;street.session.player.SetPaused(false);street.boss.AutoFire=false;Place(street.session.player,174);yield return new WaitForSeconds(.3f);street.boss.health.Hit(10000,CombatTeam.Player);yield return new WaitForSecondsRealtime(1.5f);
        var exit=FindAnyObjectByType<CampaignExit>();Check(street.Complete && exit && exit.next.gameObject.activeInHierarchy,"La misión 1 ofrece continuar a la fábrica");street.session.player.GetComponent<PlayerCombat>().SetMachineGun(true);street.session.player.GetComponent<GrenadeInventory>().Give(4);exit.Continue();while(SceneManager.GetActiveScene().name!="FabricaAutomatizada")yield return null;yield return null;
        var m=FindAnyObjectByType<CampaignMission>();Setup(m);var p=m.session.player;var gun=p.GetComponent<PlayerCombat>();var inv=p.GetComponent<GrenadeInventory>();Check(gun.HasMachineGun && inv.Count==4,"La transición conserva metralleta y granadas");Check(m.number==2 && m.objectives.Length==2 && m.DestroyedCount==0,"La fábrica comienza con dos generadores intactos");Check(FindObjectsByType<AssemblyBelt>(FindObjectsSortMode.None).Length==4,"La fábrica contiene cuatro líneas de ensamblaje animadas");
        int turrets=0;foreach(var e in FindObjectsByType<StreetEnemy>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(e.kind==StreetEnemyKind.Torreta)turrets++;Check(turrets==3,"Hay tres torretas de seguridad");
        Place(p,5);yield return new WaitForSeconds(.2f);Check(inv.Count==7,"El suministro de la fábrica entrega tres granadas");m.session.health.Hit(50,CombatTeam.Robot);Place(p,59);yield return new WaitForSeconds(.2f);Check(m.session.health.Current==85,"El botiquín recupera 35 puntos de salud");
        Place(p,30.8f);p.visual.flipX=false;int hp=m.objectives[0].health.Current;gun.TryShoot();yield return new WaitForSeconds(.4f);Check(m.objectives[0].health.Current<hp,"Los disparos dañan el generador A");
        m.objectives[0].health.Hit(10000,CombatTeam.Player);yield return null;Check(m.DestroyedCount==1 && m.exitDoor.activeSelf,"Un solo generador no completa la misión");
        Place(p,67.9f);yield return new WaitForSeconds(.3f);p.TestAxis=1;p.TestJump=true;yield return new WaitForSeconds(.55f);p.TestAxis=0;yield return new WaitForSeconds(.6f);File.AppendAllText(Path.Combine(Output,"positions.txt"),"Access: "+p.transform.position+" grounded="+p.Grounded+"\n");Check(p.transform.position.y>.7f,"El salto permite subir al acceso del generador B");
        p.TestAxis=1;while(p.transform.position.x<71.5f)yield return null;p.TestAxis=0;yield return new WaitForSeconds(.15f);p.TestAxis=1;p.TestJump=true;yield return new WaitForSeconds(.6f);p.TestAxis=0;yield return new WaitForSeconds(.55f);File.AppendAllText(Path.Combine(Output,"positions.txt"),"Upper: "+p.transform.position+" grounded="+p.Grounded+"\n");Check(p.transform.position.y>1.8f,"La pasarela elevada es alcanzable con el salto actual");
        Place(p,73.7f,2);p.visual.flipX=false;hp=m.objectives[1].health.Current;gun.TryShoot();yield return new WaitForSeconds(.35f);Check(m.objectives[1].health.Current<hp,"Se puede disparar al generador elevado");Camera.main.transform.position=new Vector3(75,2,-10);Capture("fabrica.png");
        m.objectives[1].health.Hit(10000,CombatTeam.Player);Place(p,90);yield return new WaitForSeconds(.3f);Check(m.BossStarted && m.boss.health.Alive && !m.Complete,"El supervisor protege el final de la fábrica");m.session.health.Hit(1000,CombatTeam.Robot);m.session.Restart();yield return new WaitForSeconds(.2f);Check(m.DestroyedCount==2 && m.session.health.Current==100 && inv.Count==7,"El reintento conserva objetivos y suministros");
        Place(p,94);yield return new WaitForSeconds(.3f);m.boss.AutoFire=true;yield return new WaitForSeconds(5);m.boss.AutoFire=false;Check(m.session.health.Current<100,"El supervisor dispara y daña al jugador");m.boss.health.Hit(10000,CombatTeam.Player);yield return new WaitForSeconds(1.2f);Check(!m.exitDoor.activeSelf && !m.Complete,"Vencer al supervisor abre la salida sin omitir el recorrido");Place(p,114);yield return new WaitForSecondsRealtime(.4f);Check(m.Complete,"Cruzar la salida completa la misión 2");m.Continue();while(SceneManager.GetActiveScene().name!="NucleoNexo")yield return null;yield return null;
        m=FindAnyObjectByType<CampaignMission>();Setup(m);p=m.session.player;gun=p.GetComponent<PlayerCombat>();inv=p.GetComponent<GrenadeInventory>();Check(m.number==3 && gun.HasMachineGun && inv.Count==7,"La misión 3 recibe el equipamiento de la fábrica");
        Check(m.objectives[0].door.activeSelf && m.objectives[1].door.activeSelf,"Las puertas de seguridad comienzan cerradas");m.objectives[0].health.Hit(10000,CombatTeam.Player);Check(!m.objectives[0].door.activeSelf && m.objectives[1].door.activeSelf,"Cada terminal abre su propia puerta");m.objectives[1].health.Hit(10000,CombatTeam.Player);
        Place(p,106);yield return new WaitForSeconds(.4f);Check(m.BossStarted && m.boss.core && m.boss.Phase==1,"NEXO inicia su combate final en fase 1");m.boss.health.Shielded=true;hp=m.boss.health.Current;Check(!m.boss.health.Hit(100,CombatTeam.Player) && hp==m.boss.health.Current,"El escudo bloquea el daño durante su activación");m.boss.health.Shielded=false;
        var grenade=ThrownGrenade.Launch(m.boss.transform.position,1,gun);grenade.Explode();Check(m.boss.health.Current==hp-180,"Las granadas dañan el núcleo vulnerable");m.boss.health.Hit(550,CombatTeam.Player);Check(m.boss.Phase==2,"El daño activa la segunda fase");m.boss.health.Hit(600,CombatTeam.Player);Check(m.boss.Phase==3,"El núcleo entra en tercera fase al perder salud");
        Camera.main.transform.position=new Vector3(112,2,-10);Capture("nucleo.png");m.boss.AutoFire=true;yield return new WaitForSeconds(5);m.boss.AutoFire=false;yield return null;Check(m.session.health.Current<100,"Los ataques de NEXO dañan al jugador");m.boss.health.Shielded=false;m.boss.health.Hit(10000,CombatTeam.Player);yield return new WaitForSecondsRealtime(1.5f);Check(m.Complete && m.victoryPanel.activeSelf && !m.next.gameObject.activeSelf,"Destruir NEXO completa la campaña");Capture("final-campana.png");
        m.session.BackToMenu();while(SceneManager.GetActiveScene().name!="MenuPrincipal")yield return null;Check(Time.timeScale==1,"El regreso al menú restaura el tiempo");File.AppendAllText(Path.Combine(Output,"validacion.txt"),failed?"RESULTADO: ERROR":"RESULTADO: CORRECTO");Application.Quit(failed?1:0);
    }
    void Capture(string name){Canvas.ForceUpdateCanvases();var rt=new RenderTexture(1280,720,24);rt.Create();RenderPipeline.SubmitRenderRequest(Camera.main,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes(Path.Combine(Output,name),t.EncodeToPNG());RenderTexture.active=old;rt.Release();Destroy(rt);Destroy(t);}
}
}
